from collections import Counter, defaultdict

def cycles(p):
    out = {}
    for a in range(p):
        for b in range(p):
            s0 = (2*a) % p
            s1 = (2*(17*a+24*b)) % p
            s = [s0, s1]
            for k in range(2, 30):
                s.append((34*s[-1] - s[-2]) % p)
            out[(a,b)] = tuple(s)
    return out

def mulR(x,y,p): return ((x[0]*y[0]+2*x[1]*y[1])%p, (x[0]*y[1]+x[1]*y[0])%p)
ALPHA=(3,2)
def conj(x,p): return (x[0], (-x[1])%p)

def dihedral_orbit(A,B,pa,pb):
    # group generated by simultaneous alpha-shift and simultaneous conjugation
    seen=set(); stack=[(A,B)]
    while stack:
        a,b=stack.pop()
        if (a,b) in seen: continue
        seen.add((a,b))
        stack.append((mulR(ALPHA,a,pa), mulR(ALPHA,b,pb)))
        stack.append((conj(a,pa), conj(b,pb)))
    return seen

for (pa,pb) in [(9,19),(9,59)]:
    ca, cb = cycles(pa), cycles(pb)
    groups = defaultdict(list)
    for A, ta in ca.items():
        for B, tb in cb.items():
            b0 = tuple(sorted((ta[k]*pb+tb[k]) for k in range(30)))
            b1 = tuple(sorted(((-ta[k] % pa)*pb + (-tb[k] % pb)) for k in range(30)))
            P = tuple(sorted(b0 + b1))
            groups[P].append((A,B))
    ker = [(0,0),(0,3),(0,6)]  # kernel translates on 9-side (mod 9)
    def kerclose(pts):
        out=set()
        for (A,B) in pts:
            for k in ker:
                out.add((((A[0]+k[0])%pa,(A[1]+k[1])%pa), B))
        return out
    stats=Counter(); examples={}
    for P, pts in groups.items():
        if len(pts) <= 120: continue
        S=set(pts)
        # quotient by kernel: count kernel-classes
        reps=set()
        for (A,B) in pts:
            # canonical: A mod kernel -> (a, b mod 3)
            reps.add(((A[0], A[1]%3), B))
        # dihedral orbits on kernel-classes
        orbits=[]; rem=set(reps)
        while rem:
            r=next(iter(rem))
            # dihedral orbit in original params, then kernel-quotient
            orb=dihedral_orbit(r[0] if False else (r[0][0], r[0][1]), r[1], pa, pb)
            q=set((((a[0], a[1]%3), b)) for (a,b) in orb)
            orbits.append(q); rem-=q
        key=(len(pts), len(reps), len(orbits))
        stats[key]+=1
        examples.setdefault(key, pts[:4])
    print(f"pair ({pa},{pb}): big-group decomposition (groupsize, kernel-classes, dihedral-orbits-on-quotient) -> count")
    for k,v in sorted(stats.items()): print("   ",k,"->",v," e.g.",examples[k])
